@once
<template id="flow-person-button"><button type="button" class="person-button"><span class="avatar" data-initials></span><span class="min-w-0 grow"><strong class="block truncate text-[13px] font-semibold" data-name></strong><span class="mt-1" data-status></span></span></button></template>
<template id="flow-score-sheet"><section data-score-content>
<div class="person-heading mb-5 flex flex-wrap items-start gap-3"><span class="avatar size-11!" data-initials></span><div class="min-w-0 grow">@unless($vm->role==='ku'&&$vm->page==='nilai')<p class="mb-1 text-xs font-semibold text-muted" data-kind></p>@endunless<h2 class="font-brand text-xl font-semibold" data-name></h2><p class="mt-1 text-xs text-muted" data-person-meta></p>@unless($vm->role==='ku'&&$vm->page==='nilai')<p class="mt-1 text-xs text-muted" data-template-meta></p>@endunless</div><span class="status" data-status></span></div>
<div class="notice notice-warning mb-4" data-return-reason hidden></div><div class="notice mb-4" data-lock-reason hidden></div>
<p class="mb-2 text-xs text-muted" data-score-instructions>Nilai 10–100. Tekan Enter untuk pindah ke KPI berikutnya.</p>
<div class="table-wrap"><table class="data-table score-table"><thead><tr><th>No.</th><th>KPI</th><th class="numeric">Bobot</th><th class="numeric">Nilai</th><th class="numeric">Hasil</th><th data-previous-column hidden>Nilai bulan sebelumnya</th></tr></thead><tbody data-score-rows></tbody></table></div>
<div class="score-summary"><div class="min-w-0"><p class="text-[13px] font-semibold text-ink">Total nilai</p><p class="mt-0.5 text-xs text-muted"><span data-filled></span> KPI terisi · total bobot <b data-score-weight></b>% · Hasil = nilai × bobot / 100</p></div><div class="flex items-baseline gap-3"><strong class="num" data-total></strong><span class="category" data-category></span></div></div>
<p class="mt-2 text-xs text-muted" data-previous-summary hidden></p>
<div class="mt-5 grid gap-4 min-[850px]:grid-cols-2"><label><span class="label">Temuan positif <span class="font-normal text-muted">(opsional)</span></span><textarea class="field min-h-20" data-finding="positive" maxlength="10000" placeholder="Pujian, pencapaian, ide kreatif, atau inisiatif (jika ada)"></textarea><p data-read-finding="positive" class="rounded-[10px] border border-line bg-subtle px-3 py-2 text-sm leading-6" hidden></p></label><label><span class="label">Temuan negatif <span class="font-normal text-muted">(opsional)</span></span><textarea class="field min-h-20" data-finding="negative" maxlength="10000" placeholder="Catatan perbaikan, kelalaian, atau kedisiplinan (jika ada)"></textarea><p data-read-finding="negative" class="rounded-[10px] border border-line bg-subtle px-3 py-2 text-sm leading-6" hidden></p></label></div>
<details class="mt-5 border-t border-line pt-4" data-history-tab hidden><summary class="link cursor-pointer">Jejak keputusan</summary><p class="mt-3 text-xs text-muted" data-review-decision-state></p><ol data-review-history class="decision-timeline mt-3 text-xs"></ol></details>
<p class="notice notice-error mt-4" data-score-error hidden role="alert"></p></section></template>
<template id="flow-score-item"><tr><td class="text-xs text-muted" data-score-number></td><td><strong class="font-semibold" data-kpi-name></strong><span class="mt-1 block text-xs text-muted" data-kpi-meta></span></td><td class="numeric" data-label="Bobot" data-weight></td><td class="numeric" data-label="Nilai"><label><span class="sr-only" data-score-label></span><input class="score-input num" type="text" inputmode="numeric" autocomplete="off" maxlength="5" placeholder="-" data-score></label><strong data-read-score hidden></strong></td><td class="numeric font-semibold" data-label="Hasil" data-result></td><td data-previous-cell hidden><strong data-previous></strong><span class="block mt-1 text-xs" data-previous-delta></span></td></tr></template>
@endonce
